const root=document.querySelector('#main');
let lang='en';try{lang=localStorage.getItem('jiho-language')==='ko'?'ko':'en'}catch{}
const t=v=>typeof v==='object'?v[lang]:v;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=(en,ko)=>lang==='en'?en:ko;
let data,timer,index=0,lightboxItems=[],lightboxIndex=0,lightboxReturnFocus,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const url=p=>`/portfolio/${p.id}/`;
const pic=(src,alt,lazy=true)=>{const dimensions=data?.imageDimensions?.[src];return `<img src="${e(src)}" alt="${e(alt)}" ${dimensions?`width="${dimensions[0]}" height="${dimensions[1]}"`:''} ${lazy?'loading="lazy"':'loading="eager" fetchpriority="high"'} decoding="async">`};
const link=(href,text)=>`<a class="text-link" href="${href}">${text}<span aria-hidden="true">↗</span></a>`;
function cards(projects=data.projects){return projects.map((p,i)=>`<a class="card ${p.id}" href="${url(p)}"><div class="card-img">${pic(p.cover,`${p.title} — ${t(p.subtitle)}`,i>=2||p.section==='additional')}</div><div class="card-meta"><div><div class="eyebrow">${e(t(p.category))}</div><h2>${e(p.title)}</h2><p>${e(t(p.subtitle))}</p></div><span class="arrow" aria-hidden="true">↗</span></div></a>`).join('')}
function home(){const featured=data.projects.filter(p=>p.featured);index=Math.min(index,featured.length-1);const profile=data.profile;return `<section class="home"><div class="hero" aria-roledescription="carousel" aria-label="${copy('Featured projects','대표 작품')}">${featured.map((p,i)=>`<article class="slide ${p.id} ${i===index?'active':''}" aria-hidden="${i!==index}">${pic(p.cover,`${p.title} — ${t(p.subtitle)}`,i!==0)}<div class="hero-copy"><div class="eyebrow">${e(t(p.category))}</div><h1>${e(p.title)}</h1><p>${e(t(p.subtitle))}</p><a class="text-link" href="${url(p)}" tabindex="${i===index?'0':'-1'}">${copy('VIEW PROJECT','작품 보기')}<span aria-hidden="true">↗</span></a></div></article>`).join('')}<div class="slidebar"><div class="dots">${featured.map((p,i)=>`<button data-slide="${i}" aria-label="${e(p.title)}" aria-pressed="${i===index}"></button>`).join('')}</div></div></div><section class="showreel-section" id="showreel"><div class="showreel-heading"><h2>SHOWREEL</h2></div><div class="showreel-frame"><iframe src="https://www.youtube-nocookie.com/embed/9snVCLhTVJQ?rel=0" title="Jiho Park 3D Modeling Showreel" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div></section><section class="connect-section" id="connect"><div class="eyebrow">CONNECT</div><div class="connect-grid"><a href="${e(profile.artstation)}" target="_blank" rel="noopener"><span>ArtStation</span><b aria-hidden="true">↗</b></a><a href="${e(profile.linkedin)}" target="_blank" rel="noopener"><span>LinkedIn</span><b aria-hidden="true">↗</b></a><a href="https://mail.google.com/mail/?view=cm&fs=1&to=a99484077%40gmail.com" target="_blank" rel="noopener"><span>Email</span><b aria-hidden="true">↗</b></a></div></section></section>`}
function portfolio(){const selected=data.projects.filter(p=>p.section!=='additional'),additional=data.projects.filter(p=>p.section==='additional');return `<section class="page portfolio-page"><section class="portfolio-group"><div class="page-heading"><div><h1>${copy('SELECTED WORK','대표 작업')}</h1></div></div><div class="grid">${cards(selected)}</div></section><section class="portfolio-group additional-work-group"><div class="page-heading"><div><h2>${copy('ADDITIONAL WORK','추가 작업')}</h2></div></div><div class="grid">${cards(additional)}</div></section></section>`}
function project(p){const title=`${p.title} — ${t(p.subtitle)}`,heroCaption=p.heroCaption?t(p.heroCaption):title;return `<article><div class="detail-top"><a class="back" href="/portfolio/">← ${copy('All projects','전체 작품')}</a><div class="project-heading"><div><h1>${e(p.title)}</h1><p>${e(t(p.subtitle))}</p></div><div class="eyebrow">${e(t(p.category))}</div></div></div><div class="page project-copy"><div class="overview"><div><p>${e(t(p.summary))}</p></div><dl class="facts"><div><dt>${copy('Scope','제작 범위')}</dt><dd>${e(t(p.focus))}</dd></div><div><dt>${copy('Tools','사용 툴')}</dt><dd>${e(p.tools)}</dd></div></dl></div></div><button class="lightbox-trigger hero-lightbox ${p.id==='head-sculpt-study'?'head-sculpt-hero':p.id==='hwarot'?'hwarot-hero':''}" type="button" data-lightbox="0" aria-label="${copy('Enlarge image','이미지 크게 보기')}: ${e(heroCaption)}">${pic(p.hero,heroCaption,false).replace('<img','<img class="detail-hero"')}</button>${p.heroCaption?`<div class="detail-hero-caption">${e(heroCaption)}</div>`:''}<div class="page project-gallery"><div class="gallery">${p.gallery.map((g,i)=>`<figure class="${g.layout==='half'?'gallery-half':''}"><button class="lightbox-trigger" type="button" data-lightbox="${i+1}" aria-label="${copy('Enlarge image','이미지 크게 보기')}: ${e(t(g.caption))}">${pic(g.src,t(g.caption))}</button><figcaption>${e(t(g.caption))}</figcaption></figure>`).join('')}</div></div></article><dialog class="lightbox" aria-label="${copy('Expanded portfolio image','확대된 포트폴리오 이미지')}"><div class="lightbox-toolbar"><span class="lightbox-count" aria-live="polite"></span><button class="lightbox-close" type="button" aria-label="${copy('Close enlarged image','확대 이미지 닫기')}">×</button></div><button class="lightbox-nav lightbox-prev" type="button" aria-label="${copy('Previous image','이전 이미지')}">←</button><figure class="lightbox-figure"><img alt=""><figcaption></figcaption></figure><button class="lightbox-nav lightbox-next" type="button" aria-label="${copy('Next image','다음 이미지')}">→</button></dialog>`}
function resume(){const p=data.profile;return `<section class="page"><div class="eyebrow">${copy('Résumé','리쥬메')}</div><h1 class="resume-title">${e(lang==='ko'?p.nameKo:p.name)}<span style="color:var(--muted)">.</span></h1><div class="resume-layout"><aside><p class="intro">${e(t(p.intro))}</p><p class="location">${e(p.role)}<br>${e(t(p.specialties))}<br><br>${e(t(p.location))}</p><div class="contact">${link(`tel:${p.phone.replaceAll('-','')}`,e(p.phone))}${link('https://mail.google.com/mail/?view=cm&fs=1&to=a99484077%40gmail.com',e(p.email))}${link(p.artstation,'ArtStation')}${link(p.linkedin,'LinkedIn')}</div></aside><div><section class="resume-section"><h2>${copy('Skills','기술')}</h2>${p.skillGroups.map(x=>`<h3>${e(t(x.name))}</h3><p>${e(x.tools)}</p>`).join('')}</section><section class="resume-section"><h2>${copy('Awards & recognition','수상 및 선정')}</h2>${p.awards.map(x=>`<div class="entry"><h3>${e(t(x.detail))}</h3><span class="date">${e(x.date)}</span></div><p>${e(t(x.name))}</p>`).join('')}</section><section class="resume-section"><h2>${copy('Education & training','학력과 교육')}</h2>${p.education.map(x=>`<div class="entry"><h3>${e(t(x.name))}</h3><span class="date">${e(x.date)}</span></div><p>${e(t(x.detail)).replaceAll('\n','<br>')}</p>`).join('')}</section></div></div></section>`}
function slide(n){const slides=[...document.querySelectorAll('.slide')];if(!slides.length)return;index=(n+slides.length)%slides.length;slides.forEach((s,i)=>{s.classList.toggle('active',i===index);s.setAttribute('aria-hidden',String(i!==index));s.querySelector('a').tabIndex=i===index?0:-1});document.querySelectorAll('[data-slide]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)))}
function start(){clearInterval(timer);if(!paused&&!document.hidden&&document.querySelector('.hero'))timer=setInterval(()=>slide(index+1),6500)}
function controls(){slide(index);document.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{slide(Number(b.dataset.slide));start()});const hero=document.querySelector('.hero');hero.addEventListener('mouseenter',()=>clearInterval(timer));hero.addEventListener('mouseleave',start);hero.addEventListener('focusin',()=>clearInterval(timer));hero.addEventListener('focusout',start);let touch;hero.addEventListener('touchstart',ev=>touch=ev.changedTouches[0].clientX,{passive:true});hero.addEventListener('touchend',ev=>{const delta=ev.changedTouches[0].clientX-touch;if(Math.abs(delta)>45){slide(index+(delta<0?1:-1));start()}},{passive:true});start()}
function updateLightbox(){const item=lightboxItems[lightboxIndex],box=document.querySelector('.lightbox');if(!item||!box)return;const img=box.querySelector('img');img.src=item.src;img.alt=item.alt;box.querySelector('figcaption').textContent=item.caption;box.querySelector('.lightbox-count').textContent=`${lightboxIndex+1} / ${lightboxItems.length}`;box.querySelector('.lightbox-prev').hidden=lightboxItems.length<2;box.querySelector('.lightbox-next').hidden=lightboxItems.length<2}
function moveLightbox(step){lightboxIndex=(lightboxIndex+step+lightboxItems.length)%lightboxItems.length;updateLightbox()}
function setupLightbox(p){const box=document.querySelector('.lightbox');if(!box)return;const heroCaption=p.heroCaption?t(p.heroCaption):`${p.title} — ${t(p.subtitle)}`;lightboxItems=[{src:p.hero,alt:heroCaption,caption:heroCaption},...p.gallery.map(g=>({src:g.src,alt:t(g.caption),caption:t(g.caption)}))];document.querySelectorAll('[data-lightbox]').forEach(button=>button.onclick=()=>{lightboxReturnFocus=button;lightboxIndex=Number(button.dataset.lightbox);updateLightbox();box.showModal();document.body.classList.add('lightbox-open');box.querySelector('.lightbox-close').focus()});box.querySelector('.lightbox-close').onclick=()=>box.close();box.querySelector('.lightbox-prev').onclick=()=>moveLightbox(-1);box.querySelector('.lightbox-next').onclick=()=>moveLightbox(1);box.onclick=ev=>{if(ev.target===box)box.close()};box.addEventListener('close',()=>{document.body.classList.remove('lightbox-open');lightboxReturnFocus?.focus()})}
function render(focus=false){clearInterval(timer);const path=location.pathname.replace(/\/$/,'')||'/';const p=data.projects.find(x=>path===`/portfolio/${x.id}`);let nav='home',title='Jiho Park — 3D Modeler';if(path==='/'){root.innerHTML=home()}else if(path==='/portfolio'){nav='portfolio';root.innerHTML=portfolio();title='Portfolio — Jiho Park'}else if(path==='/resume'){nav='resume';root.innerHTML=resume();title='Résumé — Jiho Park'}else if(p){nav='portfolio';root.innerHTML=project(p);title=p.title+' — Jiho Park'}else{root.innerHTML=`<section class="page"><h1>${copy('Page not found','페이지를 찾을 수 없습니다')}</h1>${link('/portfolio/',copy('View portfolio','포트폴리오 보기'))}</section>`}document.body.classList.toggle('is-home',path==='/');document.body.classList.toggle('is-resume',path==='/resume');document.title=title;document.documentElement.lang=lang;document.querySelectorAll('[data-nav]').forEach(a=>{a.removeAttribute('aria-current');if(a.dataset.nav===nav)a.setAttribute('aria-current','page')});document.querySelector('#language').textContent=lang==='en'?'KR':'EN';document.querySelector('#language').setAttribute('aria-label',copy('한국어로 전환','Switch to English'));if(path==='/')controls();if(p)setupLightbox(p);if(focus){root.tabIndex=-1;root.focus({preventScroll:true})}}
document.addEventListener('visibilitychange',start);document.querySelector('#language').onclick=()=>{lang=lang==='en'?'ko':'en';try{localStorage.setItem('jiho-language',lang)}catch{}render()};document.addEventListener('keydown',ev=>{const box=document.querySelector('.lightbox');if(box?.open){if(ev.key==='ArrowRight'){ev.preventDefault();moveLightbox(1)}else if(ev.key==='ArrowLeft'){ev.preventDefault();moveLightbox(-1)}return}if(!document.querySelector('.hero')||/INPUT|TEXTAREA/.test(ev.target.tagName))return;if(ev.key==='ArrowRight'){slide(index+1);start()}else if(ev.key==='ArrowLeft'){slide(index-1);start()}});
try{const embedded=document.querySelector('#site-content');if(embedded){data=JSON.parse(embedded.textContent)}else{const response=await fetch('/content.json');if(!response.ok)throw new Error('Content unavailable');data=await response.json()}render()}catch{root.innerHTML='<section class="page"><h1>Portfolio is temporarily unavailable.</h1><p>잠시 후 다시 시도해 주세요.</p><a class="text-link" href="/">Reload / 다시 불러오기</a></section>'}
